var i=`0578-qurutob`;var r=`world-0578`;var n=`TJ`;var o=`central-asia`;var a=4;var s=33;var u={en:`Qurutob`,ua:`Курутоб`};var l={en:`A traditional dish from Tajikistan, centered on plain yogurt, greek yogurt, pita bread, yellow onion. A measured home-kitchen version organized by cooking step. Greek yogurt substitutes for dried qurut in this home-style qurutob; traditional dried salted yogurt is absent.`,ua:`Традиційна страва кухні країни Таджикистан. Основні складники: натуральний йогурт, грецький йогурт, піта, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування. Замість сухого куруту в цьому домашньому курутобі використано грецький йогурт; традиційного солоного продукту в каталозі немає.`};var g=[{en:`Whisk Greek yogurt with a little water until pourable. Traditional salted dried qurut is not available for this version.`,ua:`Збийте грецький йогурт із водою до текучості. Традиційного солоного сухого куруту в цьому варіанті немає.`,t:[`mixing`],m:8,i:[[`plain-yogurt`,380,`g`],[`water`,220,`ml`],[`greek-yogurt`,130,`g`]]},{en:`Toast these ingredients over medium heat for about 7 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 7 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:7,i:[[`pita-bread`,5,`pcs`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,220,`g`],[`extra-virgin-olive-oil`,55,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`tomato`,330,`g`],[`cucumber`,200,`g`],[`parsley`,25,`g`]]}];var d={slug:i,id:r,country:`TJ`,region:o,servings:4,minutes:33,title:u,text:l,steps:g};export{n as country,d as default,r as id,s as minutes,o as region,a as servings,i as slug,g as steps,l as text,u as title};